      "note": "Lên đỉnh Langbiang hít gió núi, săn mây và ngắm cả một vùng Đà Lạt thu nhỏ dưới chân."
    },
    {
      "poi_id": "p187",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tô hủ tíu nóng, nước dùng trong veo, ăn kèm rau tươi kiểu người Đà Lạt."
    },
    {
      "poi_id": "p129",
      "kind": "activity",
      "must_do_id": null,
      "note": "Thung lũng tình yêu đi dạo thong thả, chụp ảnh với vườn hoa và hồ nước lặng."
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": null,
      "note": "Dinh III nhìn đồ vật cũ kể chuyện vua Bảo Đại, vườn thông phía sau mát rượi."
    },
    {
      "poi_id": "p33",
      "kind": "meal",
      "must_do_id": null,
      "note": "Góc nhỏ trong hẻm nghệ sĩ, ngồi xuống ăn bữa tối ấm cúng giữa tranh và đèn vàng."
    },
    {
      "poi_id": "p20",
      "kind": "activity",
      "must_do_id": null,
      "note": "Chợ đêm nhộn nhịp, đi lòng vòng ngửi mùi bắp nướng, sữa đậu nành và đồ ăn vặt."
    }
  ]
}
```

